from pathlib import Path
from lesson_authoring import entry as E
B=[['拉丁前缀 se-／sed-','分开；离开；到一边']]
W=[
E('sedition','/sɪˈdɪʃən/','煽动叛乱；鼓动反抗权威的言行','原本同在一个政治秩序里，有人鼓动大家与它对立、脱离或反抗。','经古法语 sedicion 或直接来自拉丁 seditio，字面是分开走：sed- 分开 + itio 行走，后者来自 ire 走。',B+[['拉丁 sed- + itio → seditio','分开走，继而指纷争、叛乱'],['古法语 sedicion → 英语 sedition','后来常指煽动反抗既有权威的言行']],'常出现在政治史和法律报道里，含义比普通不满或反对强得多。阅读时注意是谁把某些话称为 sedition：这个标签可能正是争议的一部分。词源中的“分开走”不是现代法律定义，具体法律标准也不能从拆词推出。','accusations of sedition；be charged with sedition；a debate over sedition。','dissent 是表达异议，sedition 涉及煽动反抗的指控或概念。不能把正常批评自动翻成 sedition。',('The historian examined how the government used accusations of sedition.','历史学家研究了当时政府如何使用煽动叛乱的指控。'),('The debate centred on the distinction between dissent and sedition.','争论的焦点是表达异议与煽动叛乱之间的区别。'),sources=['https://www.etymonline.com/word/sedition','https://www.merriam-webster.com/dictionary/sedition']),
E('seditious','/sɪˈdɪʃəs/','煽动叛乱的；被认为鼓动反抗权威的','给一篇文章或一次演说贴上政治性很强的标签：它被认为在鼓动人们起来反抗。','经法语 sedicios／séditieux 或直接来自拉丁 seditiosus，后者基于 seditio 纷争、叛乱。它有独立借入链，不只是在英语 sedition 后机械加 -ous。',B+[['拉丁 seditio → seditiosus','纷争、叛乱 → 煽动纷争的'],['法语相关形式 → 英语 seditious','煽动反抗的']],'常修饰 speech、writing、pamphlet、activity。它描述言论或行为被赋予的政治性质，未必是作者认可的事实；例如 allegedly seditious materials 就明确保留了“据称”的距离。','seditious speech；seditious literature；allegedly seditious material。','rebellious 可以形容孩子不服管，seditious 通常有更明确的政治和权威背景，日常小叛逆不宜随便套用。',('The authorities described the pamphlet as seditious.','当局把那本小册子描述为具有煽动叛乱性质。'),('The essay asks why some political slogans were labelled seditious.','这篇文章追问，为什么有些政治口号会被贴上煽动叛乱的标签。'),sources=['https://www.etymonline.com/word/seditious']),
E('seductive','/sɪˈdʌktɪv/','诱人的；有诱惑力的；带有性吸引力的','某种诱惑像在旁边招手，让你离开原先的打算，想朝它走过去。','基于拉丁 seducere 引到一旁的分词词干 seduct- 加 -ive；se- 离开 + ducere 引导。现代与 seduce 诱惑对应。',B+[['拉丁 se- + ducere → seducere，分词词干 seduct-','把人引到一边'],['seduct- + -ive → seductive','具有诱惑力，让人想追随的']],'可以形容人的魅力，也可以形容方案、承诺和想法。a seductive promise of easy success 是“轻松成功”的诱人承诺，常隐含它太好听、让人放下警惕；因此不限于性意味。','a seductive smile；a seductive idea；the seductive promise of success。','attractive 是有吸引力的，seductive 更强调把人吸过去、让人难以抵抗的力量，有时暗含值得警惕。',('The offer was seductive, but the conditions were unclear.','这个提议很诱人，但附带条件并不清楚。'),('The film gives its villain a calm, seductive voice.','影片让反派拥有一种平静而充满诱惑力的嗓音。'),sources=['https://www.etymonline.com/word/seductive']),
E('seductively','/sɪˈdʌktɪvli/','诱人地；富有诱惑力地','不只是把东西摆出来，而是用声音、外观或承诺让人很想靠近。','seductive + -ly，形容一种动作或呈现方式带有诱惑力。',B+[['seductive','有诱惑力的'],['seductive + -ly → seductively','以诱人的方式']],'可以修饰 smile、whisper，也能修饰形容词：seductively simple 表示简单得让人心动，往往提醒读者它可能把事情说得太容易。这个副词并不总与性吸引相关。','smile seductively；seductively simple；seductively presented。','simply 只是简单地；seductively simple 则多了“看起来太诱人”的心理效果。它既描述形式，也描述形式对人的吸引。',('The advertisement presents a seductively simple solution.','广告给出了一个简单得令人心动的解决方案。'),('She smiled seductively at him across the table.','她隔着桌子向他露出充满魅力的笑容。'),sources=['https://en.wiktionary.org/wiki/seductively','https://www.etymonline.com/word/seductive']),
E('secessionist','/sɪˈseʃənɪst/','主张脱离联盟或国家的人；分离主义者；主张分离的','一个地区本来属于更大的整体，有人主张从这个整体中退出、自成一方。','secession 脱离 + -ist 支持者；secession 来自拉丁 secessio，关联 se- 分开 + cedere 走。英语名词 secession 比现代动词 secede 的记录更早。',B+[['拉丁 secedere → secessio','走开、退出 → 脱离'],['英语 secession + -ist → secessionist','支持政治脱离的人或立场']],'可以作名词指支持脱离的人，也能放在 movement、party 前表示分离主义的。它描述政治目标，不自动说明支持者采用暴力还是和平方式，也不等于所有争取更多自治的人。','a secessionist movement；secessionist leaders；a committed secessionist。','separatist 范围更广；secessionist 更明确指退出某个现有政治共同体。autonomy 自治可以仍处于原共同体内。',('The secessionist movement called for an independent state.','这个分离主义运动主张建立独立国家。'),('The journalist interviewed both secessionists and supporters of the union.','记者采访了主张脱离的人，也采访了支持维持联盟的人。'),sources=['https://www.etymonline.com/word/secessionist'])
]
ROOT=dict(id='C1293',meaning='分开；离开；到一边',core='SE / SED = APART',image='大家原本站在一起，随后有一部分走开、被带走，或者被单独挑出来。',intro='拉丁前缀 se-、sed- 表示分离或离开。它能解释 secede 的退出、seduce 的引走，也能帮助理解 separate、secluded、select 的不同分开方式。这里的 sed- 不是“坐”的 sed-，不要把 sedition 编成坐着造反。',forms='se- 常见于 secede、separate、seclude、select；sed- 保留在 sedition。seduce 里的 duc- 是引导，secede 里的 ced- 是走；它们走向不同词义，不能只看共同前缀。',branches=[['分开与独处','separate、separation、secluded、seclusion'],['政治上的分离或对立','secede、secession、secessionist、sedition、seditious'],['把人引到一旁','seduce、seduction、seducer、seductive、seductively'],['从整体中挑出或隐藏','select、secret']],contrasts='secede 是退出共同体，sedition 是煽动反抗的概念；secluded 是远离人群的，seductive 是把注意力吸过去的。共同的 apart 只提供起点，最终意思由完整词族决定。',practice='The seductive promise of a peaceful retreat led them to book a secluded cottage.\n\n“安静休憩”的诱人承诺，让他们订下了一间远离人群的小屋。',words=[x['word'] for x in W]+['seduce','seduction','seducer','secede','secession','separate','separation','secluded','seclusion','select','secret'],exclude={})
if __name__=='__main__':
 for name,data in [('roots_se',[ROOT]),('words_se',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
